'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright');
const html=fs.readFileSync(path.resolve(__dirname,'../../index.html'),'utf8');
const css=[...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(m=>m[1]).join('\n');
const long='模组／个人偏好名称ExampleLongEnglishUnbrokenLabel0123456789'.repeat(4);
const fixture=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${css}\n/* isolate three existing content samples from modal positioning and unrelated navigation */\nbody{margin:0!important;padding:8px!important;display:grid!important;gap:12px!important;overflow-x:hidden!important}#selfIntroView,#statsView,#settingsModal{display:block!important;position:static!important;transform:none!important;inset:auto!important;max-width:760px!important;width:100%!important;height:auto!important;max-height:none!important;margin:0 auto!important;overflow:visible!important}#settingsModal .settings-layout,#settingsModal .settings-main,#settingsModal .settings-panels{display:block!important;position:static!important;height:auto!important;overflow:visible!important}#settingsModal .settings-nav{display:flex!important;flex-wrap:wrap!important;height:auto!important}#settingsModal .settings-nav button{width:auto!important;flex:1!important}#settingsModal .settings-overview-grid{display:grid!important}\n</style></head><body>
<section id="selfIntroView" class="self-intro-view"><div class="self-intro-side pl"><header class="self-intro-side-head"><div><span class="self-intro-side-kicker">PL 偏好</span><strong>作为玩家</strong><small>${long}</small></div></header><div class="self-intro-side-body"><section class="intro-major-group"><div class="intro-major-group-body"><div class="self-intro-section-head"><strong>${long}</strong><span>可多选；按需填写</span><div class="self-intro-section-tools"><button class="intro-toggle-all">全选</button></div></div><div class="intro-chip-grid"><label class="intro-chip"><input type="checkbox"><span>${long}</span></label><label class="intro-chip"><input type="checkbox"><span>短选项</span></label></div><div class="intro-scale"><div class="intro-scale-head"><strong>${long}</strong><output>一般</output></div><div class="intro-scale-track">${Array.from({length:5},(_,i)=>`<button class="intro-scale-step" type="button"><i class="intro-scale-dot"></i></button>`).join('')}</div><div class="intro-scale-labels"><span>${long}</span><span>中间</span><span>${long}</span></div></div></div></section></div></div><div class="self-intro-summary-scales"><span><b>${long}</b><em>喜欢</em></span></div></section>
<section id="statsView" class="stats-view"><article class="stats-identity-card"><div class="stats-donut"><div class="stats-donut-center"><strong>21</strong><span>桌</span></div></div><div class="stats-identity-copy"><p>KP 与 PL 的角色分布</p><div class="stats-role-legend"><div class="stats-role-row"><i class="stats-role-dot kp"></i><span>作为 KP</span><strong>7 桌</strong></div></div></div></article><div class="stats-overview-grid"><div class="stats-metric-card"><span>累计桌次</span><strong>23</strong><small>有记录的桌</small></div></div><article class="stats-panel"><header class="stats-panel-head"><div class="stats-panel-title"><strong>一起跑团的人</strong><span>保持完整姓名，排名可阅读</span></div><div class="stats-panel-controls"><div class="stats-segmented"><button>全部</button><button>我做 KP</button></div></div></header><div class="stats-panel-body"><div class="stats-ranking"><div class="stats-ranking-row"><span class="stats-rank-no">1</span><div class="stats-rank-main"><strong class="stats-rank-name">${long}</strong><span class="stats-rank-meta">近期一起参加过相关模组</span></div><div class="stats-rank-value"><strong>24</strong><span>桌</span></div></div></div><div class="stats-bars"><div class="stats-bar-row"><div class="stats-bar-label">${long}</div><div class="stats-bar-track"><div class="stats-bar-fill" style="width:66%"></div></div><strong class="stats-bar-value">66%</strong></div></div><div class="stats-table-wrap"><table class="stats-table"><thead><tr><th>模组</th><th>场次</th></tr></thead><tbody><tr><td>${long}</td><td>10</td></tr></tbody></table></div><p class="stats-footnote">统计数据说明与使用规则</p></div></article></section>
<section id="settingsModal" class="modal settings-modal"><div class="settings-layout"><nav class="settings-nav"><button>概览</button><button>数据与备份</button><button>显示设置</button><button>高级工具</button></nav><main class="settings-main"><div class="settings-panels"><section class="settings-purpose-section"><div class="settings-purpose-heading"><h3>当前本地档案</h3><p>${long}</p></div><div class="friendly-data-head"><div><strong>完整备份</strong><span>${long}</span></div></div><div class="settings-overview-grid"><button><span>档案情况</span><strong>31 份</strong><small>${long}</small></button><button><span>程序版本</span><strong>v8.1.12.197</strong><small>本机使用</small></button></div></section></div></main></div></section></body></html>`;
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox']});try{for(const width of [1440,900,390,320]){const page=await browser.newPage({viewport:{width,height:900}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.setContent(fixture);const d=await page.evaluate(()=>{const q=s=>document.querySelector(s),f=s=>parseFloat(getComputedStyle(q(s)).fontSize),r=s=>q(s).getBoundingClientRect(),scroll=s=>q(s).scrollWidth-q(s).clientWidth;const pick=['#selfIntroView .intro-chip span','#selfIntroView .intro-scale-labels','#statsView .stats-ranking-row','#statsView .stats-bar-row','#settingsModal .settings-overview-grid button'];return{docOverflow:document.documentElement.scrollWidth-innerWidth,chipFont:f('#selfIntroView .intro-chip span'),chipH:r('#selfIntroView .intro-chip span').height,scaleFont:f('#selfIntroView .intro-scale-labels'),step:r('#selfIntroView .intro-scale-step').width,rankFont:f('#statsView .stats-rank-name'),rankMetaFont:f('#statsView .stats-rank-meta'),rankOverflow:scroll('#statsView .stats-ranking-row'),barOverflow:scroll('#statsView .stats-bar-row'),tableFont:f('#statsView .stats-table td'),btnH:r('#statsView .stats-segmented button').height,settingsHintFont:f('#settingsModal .settings-overview-grid button>small'),settingsLabelFont:f('#settingsModal .settings-overview-grid button>span'),settingsHintOverflow:scroll('#settingsModal .settings-overview-grid button'),navH:r('#settingsModal .settings-nav button').height,offenders:pick.filter(s=>r(s).right>innerWidth+2).map(s=>({s,rect:r(s).toJSON()}))};});assert(d.docOverflow<=1,`${width}px document overflow ${d.docOverflow}`);assert(d.chipFont>=11.5&&d.scaleFont>=11,`${width}px preferences too small`);assert(d.rankFont>=12&&d.rankMetaFont>=11&&d.tableFont>=11.5,`${width}px stats too small`);assert(d.settingsHintFont>=11&&d.settingsLabelFont>=11.5,`${width}px settings too small`);assert(d.rankOverflow<=1&&d.barOverflow<=1&&d.settingsHintOverflow<=1,`${width}px content box overflow`);assert.equal(d.offenders.length,0,`${width}px content extends beyond viewport`);if(width<=760){assert(d.step>=40&&d.btnH>=42&&d.navH>=44,`${width}px mobile touch targets: ${JSON.stringify(d)}`);}assert.equal(errors.length,0,`${width}px page errors`);console.log(`${width}px: preference ${d.chipFont}px, stats ${d.rankFont}px, settings ${d.settingsHintFont}px; overflow 0; page errors 0`);await page.close();}}finally{await browser.close();}})().catch(err=>{console.error(err);process.exitCode=1});
